#!/bin/bash
# git-workflow.sh — Automated git workflow for SDLC Agent
# Executes: branch → commit → push → glab mr create --draft
#
# Usage: ./git-workflow.sh <FormattedID> <title> [target_branch]
#
# Arguments:
#   FormattedID  - Rally issue ID (e.g., US12345)
#   title        - Issue title for branch naming and commit message
#   target_branch - (optional) Target branch for MR, defaults to 'main'
#
# This script is designed to be run by the SDLC Automation Agent.
# It follows safety-first principles: --draft MRs, conventional commits,
# no force pushes.

set -euo pipefail

# --- Arguments ---
FORMATTED_ID="${1:?Error: FormattedID is required (e.g., US12345)}"
TITLE="${2:?Error: Title is required}"
TARGET_BRANCH="${3:-main}"

# --- Derive values ---
# Sanitize title for branch name: lowercase, replace spaces with hyphens, truncate
SANITIZED_TITLE=$(echo "$TITLE" | tr '[:upper:]' '[:lower:]' | tr ' ' '-' | sed 's/[^a-z0-9-]//g' | head -c 50)
BRANCH_NAME="feature/${FORMATTED_ID}-${SANITIZED_TITLE}"
COMMIT_MSG="feat(${FORMATTED_ID}): ${TITLE}

- Implements requirements from Rally ${FORMATTED_ID}
- See .docs/requerimientos.md for full specification
- See .docs/diseño.md for technical design

Rally-Issue: ${FORMATTED_ID}"

echo "=== SDLC Git Workflow ==="
echo "Rally ID:      ${FORMATTED_ID}"
echo "Title:         ${TITLE}"
echo "Branch:        ${BRANCH_NAME}"
echo "Target:        ${TARGET_BRANCH}"
echo ""

# --- Pre-flight checks ---
echo "--- Pre-flight Checks ---"

# Check git is available
if ! command -v git &>/dev/null; then
    echo "ERROR: git is not installed or not in PATH"
    exit 1
fi
echo "✅ git available"

# Check glab is available
if ! command -v glab &>/dev/null; then
    echo "ERROR: glab is not installed or not in PATH"
    echo "Install: brew install glab (Mac) / winget install GLab.GLab (Windows)"
    exit 1
fi
echo "✅ glab available"

# Check glab auth
if ! glab auth status &>/dev/null; then
    echo "ERROR: glab is not authenticated. Run: glab auth login"
    exit 1
fi
echo "✅ glab authenticated"

# Check we're in a git repo
if ! git rev-parse --is-inside-work-tree &>/dev/null; then
    echo "ERROR: Not inside a git repository"
    exit 1
fi
echo "✅ Inside git repository"

# Check remote exists
if ! git remote get-url origin &>/dev/null; then
    echo "ERROR: No 'origin' remote configured"
    exit 1
fi
echo "✅ Remote 'origin' exists"

echo ""

# --- Step 1: Create branch ---
echo "--- Step 1: Create Feature Branch ---"
git checkout -b "$BRANCH_NAME"
echo "✅ Created and switched to branch: $BRANCH_NAME"
echo ""

# --- Step 2: Stage and commit ---
echo "--- Step 2: Stage and Commit ---"
git add .
git commit -m "$COMMIT_MSG"
echo "✅ Changes committed"
echo ""

# --- Step 3: Push to remote ---
echo "--- Step 3: Push to Remote ---"
git push -u origin HEAD
echo "✅ Pushed to origin/$BRANCH_NAME"
echo ""

# --- Step 4: Create Draft MR ---
echo "--- Step 4: Create Draft Merge Request ---"
MR_OUTPUT=$(glab mr create \
    --title "feat(${FORMATTED_ID}): ${TITLE}" \
    --description-file .docs/report.md \
    --target-branch "$TARGET_BRANCH" \
    --source-branch "$BRANCH_NAME" \
    --draft \
    --assignee @me \
    --label "bot-generated,${FORMATTED_ID}" \
    --yes 2>&1)

echo "$MR_OUTPUT"

# Extract MR URL from output
MR_URL=$(echo "$MR_OUTPUT" | grep -oP 'https://[^\s]+merge_requests/\d+' | head -1 || echo "")
MR_IID=$(echo "$MR_URL" | grep -oP '\d+$' || echo "")

echo ""
echo "=== Workflow Complete ==="
echo "BRANCH_NAME:${BRANCH_NAME}"
echo "MR_URL:${MR_URL}"
echo "MR_IID:${MR_IID}"

# --- Step 5: Add automated note to MR ---
if [ -n "$MR_IID" ]; then
    echo ""
    echo "--- Step 5: Add Automated Note ---"
    glab mr note create "$MR_IID" \
        -m "## 🤖 Automated SDLC Report

**Rally Issue:** ${FORMATTED_ID}
**Specification:** See \`.docs/requerimientos.md\` and \`.docs/diseño.md\`

This MR was generated by the SDLC Automation Agent.
Please review the draft and mark as ready when approved."

    echo "✅ Note added to MR #${MR_IID}"
fi

echo ""
echo "🎉 Git workflow completed successfully!"
